"""AQS-COM-003 performance test (X-COM-03, A-M-202). Bounding feed case: AQS-ASSAY-001 class A at the design feed rate (drivers
feed_rate_kg_d, feed_case_A_*). Guarantee points are every present edge into a product node and the plant power total; each is
measured over a 72 h run at steady state, by the flow transmitter on that stream where AQS-CTL-001 has one, else by weighed batch.
Tolerance: mass rates +/- 10 %, power + 10 % (A-M-202). Plant mass balance closure within 2 % over the run.
Run after _instr_index.py: python3 docs-authority/_perf_test.py"""
import json, os, sys, csv
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); os.chdir(R); sys.path.insert(0, R)
from flow_graph.param.refs import cite
from flow_graph.param import drivers as DR
cite('LUNAR_SOURCEBOOK'); cite('PERRY9')
d = DR.load(); feed = DR.val(d, 'feed_rate_kg_d')
g = json.load(open('flow_graph/plant_flow_graph.json')); N = {n['unit_id']: n for n in g['nodes']}
FT = {}
for r in csv.DictReader(open('docs-authority/inventory/INSTRUMENT_INDEX.csv')):
    if '-FT-' in r['tag']: FT.setdefault(r['basis'].split(' ')[0], r['tag'])
rows = []
for e in g['edges']:
    b = N.get(e['to_unit_id']) or {}
    if e['presence'] == 'present' and (b.get('class') in ('product', 'cut_tank') or e['to_unit_id'] == 'BOUNDARY_EXPORT') and e['rate'].get('unit') == 'kg/d' and (e['rate'].get('value') or 0) > 0:
        q = e['rate']['value']; u = e['rate'].get('unit')
        rows.append((e['to_unit_id'], e['stream_id'], e['from_unit_id'], q, u, FT.get(e['stream_id'], 'weighed batch (scale, 0.1 % FS)')))
rows.sort()
EW = [e for e in g['edges'] if e['presence'] == 'present' and (N.get(e['from_unit_id']) or {}).get('class') in ('ew_cell', 'ew', 'electrowinning') and e.get('phase') == 'S' and (e['rate'].get('value') or 0) > 0]
rows += [(f"metal from {e['from_unit_id']}", e['stream_id'], e['from_unit_id'], e['rate']['value'], e['rate'].get('unit'), 'weighed cathode harvest') for e in EW]
h2 = [e for e in g['edges'] if e['presence'] == 'present' and e['from_unit_id'] == 'H2O_ELYZ' and (e.get('composition') or {}).get('H2', 0) > 0.5]
rows += [('H2 to bank', e['stream_id'], 'H2O_ELYZ', e['rate']['value'], e['rate'].get('unit'), FT.get(e['stream_id'], 'thermal mass flow meter')) for e in h2]
GEN = ('pv', 'pem_fc', 'iem_fc', 'genset', 'flow_battery')   # sources, not loads (X-QA-02 QC-05 finding)
kw = sum(float(((n.get('continuous_kw') or {}).get('value') if isinstance(n.get('continuous_kw'), dict) else n.get('continuous_kw')) or 0) for n in g['nodes'] if n.get('presence', 'present') == 'present' and n.get('class') not in GEN and n['unit_id'] not in ('GEO_ORC',))   # R11 Rev AC regen: foundry IND_MELT/RF_HEAT/VAC_IND carry scalar continuous_kw
md = ['# Performance test', '', 'Document number: AQS-COM-003', 'Revision: B', 'Date: 2026-10-25',
      'Authority: AQS-PLAN-007 task X-COM-03; assumption A-M-202. Generated by `docs-authority/_perf_test.py` from the plant flow graph; do not edit this page by hand. Study.', '',
      '| Rev | Description | Date |', '|---|---|---|', '| A | First issue | 2026-10-16 |',
      '| B | Purpose and scope added; text rewritten to the documentation style guide (AQS-DOC-002). The plant load row is now part of Table 3.1. No guarantee point or pass band changed. | 2026-10-25 |', '',
      '## 1. Purpose and scope', '',
      'The performance test shows, after commissioning, that the plant makes its products at the rates the design predicts and uses no more '
      'power than the design allows. This page defines the test case, the pass criteria and the guarantee points: each product stream, the '
      'rate given for it in the flow graph, how it is measured, and the band within which the measured rate must fall.', '',
      '## 2. Test case and pass criteria', '',
      f'The test uses the bounding case, the class A feed of AQS-ASSAY-001 at {feed:.2f} kg/d. The plant runs for 72 h at steady state, '
      'starting after step 6 of the commissioning procedure AQS-COM-002. The test passes if every measured mass rate is within 10 % of its '
      'graph rate, if the plant power is no more than 10 % above the graph total, and if the mass balance closes within 2 %.', '',
      'A point that fails is run again once after a hold of 24 h. If it fails a second time, a design query is raised against the sizing module of the unit.', '',
      '## 3. Guarantee points', '',
      'Table 3.1 lists the guarantee points. Products to product tanks are listed first, then the metal harvested from each electrowinning cell, and last the plant load. Rates are those of the graph at the time of generation.', '',
      'Table 3.1. Guarantee points', '',
      '| Product | Stream | From | Graph rate | Unit | Measured by | Pass band |', '|---|---|---|---|---|---|---|']
md += [f'| {a} | {s} | {f} | {q:.4g} | {u} | {m} | {0.9*q:.4g} - {1.1*q:.4g} |' for a, s, f, q, u, m in rows]
md += [f'| Plant load (sum of the continuous loads of all consumers, excluding the PV array, fuel cells, generator set, battery and ORC unit) | - | - | {kw:.1f} | kW | revenue-grade meter at LOAD_AGG | <= {1.1*kw:.1f} |', '',
       f'The table has {len(rows)} product guarantee points and one plant load point.']
open('docs-authority/PERF_TEST.md', 'w').write('\n'.join(md) + '\n'); print(len(rows), kw, sum(1 for r in rows if 'FT' in r[5]))
